void printMatrix2(float* matrix, int row, int col) {

    for(int i=0;i<row;i++)

    {

        std::cout << std::endl;

        std::cout << " [ ";

        for (int j=0; j<col; j++) {

         std::cout << matrix[i][j] << " ";

        }

        std::cout << " ] ";

    }

    std::cout << std::endl;

}
